$ErrorActionPreference='Stop';$Run='C:\Users\aaron\Desktop\URAP\artifacts\detached_ard100_yolomg_train_candidates_v86';$StatePath=Join-Path $Run 'state.json'
if(-not(Test-Path $StatePath)){Write-Host 'status: NOT RUNNING';Write-Host 'done/total: 0/106734';exit 0}
$State=Get-Content $StatePath -Raw|ConvertFrom-Json;$Process=Get-CimInstance Win32_Process -Filter "ProcessId=$($State.pid)" -ErrorAction SilentlyContinue
$Labels=Join-Path $State.output_dir 'labels';$SavedLabels=if(Test-Path $Labels){(Get-ChildItem $Labels -File -Filter *.txt -ErrorAction SilentlyContinue).Count}else{0};$BatchDone=0;$BatchTotal=[int]$State.total_batches;$ProgressLog=if((Test-Path $State.stderr)-and (Get-Item $State.stderr).Length -gt 0){$State.stderr}else{$State.stdout};if(Test-Path $ProgressLog){$Tail=(Get-Content $ProgressLog -Tail 120)-join "`n";$Matches=[regex]::Matches($Tail,'(\d+)/(\d+)');if($Matches.Count){$Last=$Matches[$Matches.Count-1];$BatchDone=[int]$Last.Groups[1].Value;$BatchTotal=[int]$Last.Groups[2].Value}};$Done=[math]::Min([int]$State.total_images,$BatchDone*[int]$State.batch_size)
